INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178894, 659609, 'Técnico/a en electrónica p/ Lab. de informática', 'Javier Coccaro', 'Desde hace más de 35 años, asistimos a grandes, medianas y pequeñas empresas en el mantenimiento de equipos informáticos y la provisión de hardware y software. Nuestro equipo de técnicos atiende más de puestos de trabajo en todo el país en conjunto con el asesoramiento, diagramación, estructuración, implementación y configuración de datacenters. También realizamos la operación de reparación local (ICR, In Country Repair) para distintas marcas líderes. Importante empresa nacional de servicios informáticos y representante de marcas líderes busca Técnicos/as en Electrónica para incorporar a su laboratorio con el propósito de:- Reparar motherboards y placas electrónicas, diagnosticando y analizando fallas típicas con ayuda de esquemáticos y Gerbers.- Testear equipos reparados.- Documentar y registrar en el sistema de la empresa las intervenciones realizadas de acuerdo con las normas ISO 9000. Requisitos: Para ello, buscamos:- Que seas egresado del secundario técnico con especialidad en electrónica.- Que tengas conocimientos acerca de componentes informáticos, pref. de notebooks (excluyente).- Que tengas alguna experiencia comprobable en tareas de reparación de motherboards de notebooks y/o placas electrónicas, utilizando cautín u otras técnicas de soldadura (excluyente).- En alternativa: serán considerados candidatos sin experiencia laboral previa que hayan realizado “Practicas Profesionalizantes” mediadas por la escuela técnica y estrictamente relacionadas con las tareas enunciadas.Son requisitos indispensables que poseas conocimientos demostrables en:- Lectura y análisis de esquemáticos.- Cálculo de tensiones, resistencias y corrientes de un circuito.- Soldadura SMD por aire y por contacto.- Manejo de osciloscopio para mediciones de señales.- Manejo completo de Tester/multímetro.- En procesos de Reballing de integrados BGA (deseable).- Armado y desarmado de notebooks/celulares. Beneficios Qué ofrece la empresa:- Trabajo estable en relación de dependencia.- Ambiente profesional y colaborativo.- Opción Swiss Medical con precios corporativos a cargo del colaborador.- Desayuno en equipo los días viernes.- Refrigerio con bebidas calientes de consumo libre y Snack de frutas.- Día de cumpleaños libre.- Modalidad 100% presencial, de lunes a viernes de a en Parque Patricios, CABA.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 07:07:30', '08-04-2026 07:07:30', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 3, 0, 19, 34, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178894.html', '2026-04-12T07:05:36.457344');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179277, 524045, 'Técnico de Laboratorio', 'Laboratorio Rapela', 'El laboratorio fue fundado en 1991 en la Ciudad Autónoma de Buenos Aires, en la calle Ramón Falcón 2534. Con una sede de más de 1000 m2 y equipado con tecnología de punta, ofrece servicios de análisis clínicos, toxicológicos, veterinarios, bromatológicos, cosméticos y farmacéuticos, así como también servicios de Clinical Trials, Diagnóstico por imagen y Servicios a Terceros.A lo largo de los años, el laboratorio ha obtenido diversas certificaciones y reconocimientos por su calidad y profesionalismo, incluyendo la Certificación ISO 9001 en el año 2000, la Acreditación ISO 15189 y la Acreditación ISO 17025 en 2005, con sus respectivas re-certificaciones en años posteriores. Además, ha sido reconocido por el COI en varias ocasiones y cuenta con la habilitación de SENASA. En Laboratorio Rapela nos encontramos en la búsqueda de Tecnico/a de Laboratorio para el área de Analisis clinicos. Posición permanente Lugar de trabajo: Flores, CABA Horario: Lunes a Sabados de 8 a 14 hs o de 7 a 13 hs ¿Cuáles serán tus tareas? Extracción de sangre en distintos centros ambulatorio e internación Toma de muestras bacteriologica Aplicación PPD Realizacion de trabajos tecnicos de mesada Manejo de equipos automatizados Control y preparacion de muestrasRequisitos: Titulo de Tecnico/a de laboratorio. Experiencia mínima de un año en el área.Te ofrecemos: Dia de cumpleaños libre Bonificación en gimnasios de primera línea Convenio con Institutos de idiomas (Liceo Británico/Open English)‍️ Te bonificamos el 100% en tus Análisis Clínicos ¡Tu mascota es familia! 50% en sus Análisis veterinarios¡Administra tu sueldo! Anticipamos hasta el 50% a mitad de mes¡Aguardamos tu postulacion! Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:03:15', '09-04-2026 15:03:15', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2570, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_524045_bum_vff225b02.jpg', 1, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179277.html', '2026-04-12T07:05:36.457486');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179148, 520049, 'Tecnico de Laboratorio', 'Casa Hospital San Juan de Dios', 'La Orden Hospitalaria de San Juan de Dios, presente en 50 países alrededor del mundo, cuenta con 400 centros, 1100 Hermanos y Colaboradores que continúan el legado de la misión de Hospitalidad de San Juan de Dios, iniciada hace más de 500 años...Nuestra Casa Hospital, perteneciente a la Orden Hospitalaria, es de confesionalidad católica, privado y sin fines de lucro. Nuestro objetivo es brindar prestaciones asistenciales de salud basadas en servicios de alta complejidad para el cuidado integral de los pacientes de zona oeste del GBA, fusionando conocimiento científico y tecnología de avanzada y una contención espiritual permanente. NUESTROS VALORES Hospitalidad: Definida como “acoger incondicionalmente a las personas, respetando su dignidad, cuidando y promoviendo integralmente su vida.”Calidad: Excelencia, profesionalidad, atención holística, conciencia de las nuevas necesidades, modelo de unión con nuestros Colaboradores, modelo de atención juandediana, arquitectura y decorado acogedores, colaboración con terceros.Respeto: Respeto por el prójimo, humanización, dimensión humana, responsabilidad recíproca para con los Colaboradores y Hermanos, comprensión, visión holística, promoción de la justicia social, derechos civiles y humanos, implicación de los familiares.Responsabilidad: Fidelidad a los ideales de San Juan de Dios y de la Orden, ética (bioética, ética social, ética de gestión) protección del medio ambiente, responsabilidad social (para los europeos: la Unión Europea), sostenibilidad, justicia, justa distribución de los recursos.Espiritualidad: Para guiar a cada persona en la búsqueda de significado, de religión y de lo trascendental: pastoral de la salud, evangelización, ofrecer atención espiritual a los miembros de otras religiones, ecumenismo, colaboración con parroquias, diócesis, otras confesiones religiosas. Casa Hospital San Juan de Dios se encuentra en la búsqueda de un/a Técnico/a de Laboratorio para cubrir los días sábados de 07 a 11 hs, en nuestra sede ubicada en la localidad de Castelar. Responsabilidades principales: Realizar extracciones de sangre en pacientes adultos y pediátricos Toma de muestras micológicas y bacteriológicas Análisis de orinaCondiciones de la posición: Jornada: sábados de 07 a 11 hs Modalidad: presencial Contratación por 4 meses, con posibilidad de extensión Requisitos: Requisitos: Título de Técnico/a de Laboratorio Matrícula provincial vigente', 0, 'Castelar, Buenos Aires', 'Presencial', 'Por Contrato', '08-04-2026', '08-04-2026 12:08:10', '08-04-2026 12:08:10', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2520, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_520049_bum_v3ba1486b.jpg', 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179148.html', '2026-04-12T07:05:36.457638');
