INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179016, 679137, 'Técnico de Laboratorio de Preparados Magistrales', 'farmacia paracelso', 'Técnico de Laboratorio de Preparados Magistrales Resumen del Puesto Buscamos un Técnico de Laboratorio con experiencia en la elaboración de preparados magistrales y oficinales para unirse a nuestro equipo. El candidato ideal demostrará solvencia en el desempeño de sus funciones y poseerá conocimientos específicos en dermocosmética y manejo de maquinaria de comprimidos. Responsabilidades Elaboración de preparados magistrales y oficinales. Control de calidad de los productos elaborados. Manejo y mantenimiento de la maquinaria de laboratorio, incluyendo máquinas comprimidoras. Gestión de inventario de materias primas y productos terminados. Colaboración con el equipo para asegurar la eficiencia operativa. Requisitos Experiencia comprobable en laboratorios de preparados magistrales y oficinales. Conocimientos en dermocosmética. Experiencia en el uso de máquinas comprimidoras (preferentemente monopunzón). Capacidad para desempeñarse con solvencia y autonomía. Habilidad para trabajar en equipo y seguir procedimientos establecidos. Se valorará la presentación de referencias laborales.', 0, 'Salta, Salta', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 12:04:07', '07-04-2026 13:30:58', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2520, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179016.html', '2026-04-12T07:05:36.457852');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226489, 13510975, 'Técnico de Mantenimiento General (Eléctrico y Mecánico)', 'LA QUINQUENAL', 'Técnico de Mantenimiento General (Eléctrico y Mecánico) Resumen del Puesto Estamos en la búsqueda de un profesional con experiencia en mantenimiento general y tareas asociadas a la industria metalúrgica. El candidato ideal poseerá conocimientos sólidos en áreas eléctricas y mecánicas, demostrando capacidad para resolver incidencias y asegurar el óptimo funcionamiento de equipos e instalaciones. Se requiere dedicación a tiempo completo. Responsabilidades Realizar tareas de mantenimiento preventivo y correctivo en equipos e instalaciones. Diagnosticar y reparar averías de índole eléctrica y mecánica. Ejecutar trabajos generales de mantenimiento según las necesidades operativas. Colaborar en la mejora continua de los procesos de mantenimiento. Asegurar el cumplimiento de las normativas de seguridad durante la ejecución de las tareas. Requisitos Experiencia comprobable en mantenimiento general, con énfasis en electricidad y mecánica. Conocimientos técnicos específicos del sector metalúrgico. Capacidad para interpretar planos y diagramas técnicos. Habilidad para trabajar de forma autónoma y en equipo. Disponibilidad para jornada completa. Proactividad y orientación a la resolución de problemas.', 0, 'Ciudad Madero, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 09:54:31', '10-04-2026 09:54:31', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226489.html', '2026-04-12T07:05:36.457936');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227088, 13252943, 'Técnico Mecánio/Electro Mecánico', 'KARBON ATF SRL', 'Buscamos Técnico Mecanico/Electro Mecanico, para la fabricación de filtros de habitáculo. Se valorará experiencia en la industria y conocimiento en operación de máquinas.Turnos rotativos (mañana, tarde, noche)Se ofrece contración fija, capacitación y desarrollo.Remuneracion acorde, según convenio UOM. Indicar Remuneración Pretendida.Requisitos:Sexo Masculino.Título de técnico mecanico/electro mecanico. (Excluyente)Disponibilidad Full-Time.Conocimiento Técnico.Capacidad de trabajo en equipo.Zona de trabajo: Villa Soldati, Capital Federal', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:39:23', '10-04-2026 14:39:23', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227088.html', '2026-04-12T07:05:36.457998');
