, NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118036413.html', '2026-04-12T07:05:36.459138');
