res', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 17:48:06', '10-04-2026 17:48:06', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227530.html', '2026-04-12T07:05:36.459216');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227017, 13270453, 'Oficial de Mantenimiento', 'Obra Social Luis Pasteur', 'Nos encontramos en la búsqueda de un Técnico Oficial de Mantenimiento para unirse a nuestro equipo ubicado en la zona e CABA. Seleccionaremos a aquellas personas que posean experiencia en reparaciones, manejo de herramientas y conocimientos técnicos comprobables en electricidad, albañilería.Además, será fundamental que puedas trabajar en equipo, seas organizado/a y tengas capacidad para solucionar problemas de forma eficiente. Sus tareas serán:Realizar recorridas diarias, con el fin de chequear el buen funcionamiento del edificio y activos.Llevar a cabo tareas de mantenimiento preventivo y correctivo en nuestras instalaciones.Gestión y seguimiento de proveedores.Relevamiento y generación de inventarios.Gestión y anticipación de urgencias. Requisitos: Ser Técnico electromecánico, electricista, o Maestro Mayor de obras Contar con experiencia de al menos 2 años en puesto similar, acreditando conocimientos de tareas generales (albañilería, plomería, Gas, aire acondicionado, etc.), mantenimiento y administrativas inherentes.Buen manejo de herramientas informáticas.Habilidades comunicacionales. ​​​​​​​Contar con disponibilidad horaria: 11:30hs a 20:00hs - CABA Beneficios Medicina prepaga de primer nivel para vos y grupo familiar primario. Comedor en planta. Viernes Flex al mes. Día de cumpleaños libre. Descuentos en Gimnasioy muchos más!', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:05:51', '10-04-2026 14:05:51', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2609, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227017.html', '2026-04-12T07:05:36.459302');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227920, 319880, 'Ingeniero/a de Mantenimiento eléctrico', 'Randstad Argentina', '¡Esta propuesta te puede interesar! Para importante empresa multinacional en Villa Gobernador Gálvez estamos buscando Ingeniero/a de Mantenimiento Eléctrico para unirse a su equipo Como Ingeniero/a de Mantenimiento Eléctrico asumirás las siguientes responsabilidades: Liderazgo Operativo: Coordinar y liderar los planes de mantenimiento eléctrico para garantizar la máxima disponibilidad. Modernización Industrial: Identificar tecnologías obsoletas y liderar el avance hacia equipos de última generación. Gestión de Activos Críticos: Participar activamente en el relevamiento y provisión de equipos críticos para el corazón de nuestra producción. Estrategia Preventiva: Generar rutinas robustas para la previsión de fallas, pasando de la reacción a la proactividad. Análisis de Causa Raíz: Asistir en la resolución de problemas complejos y realizar análisis de fallos detallados. Sinergia Organizacional: Interactuar con equipos interdisciplinarios en proyectos estratégicos, trabajando codo a codo con tus aliados clave: SHE, Producción, Mantenimiento e Ingeniería. ¿Qué necesitamos de vos? Formación: Universitario completo o estudiante avanzado en Ingeniería Electrónica, Electromecánica o Eléctrica. Experiencia comprobable en áreas de Mantenimiento Eléctrico Industrial. Dominio Técnico: Conocimiento profundo de tecnologías industriales como PLC, servomotores, controladores y variadores de velocidad. Idiomas: Nivel de inglés intermedio (capacidad para lectura técnica y comunicación corporativa).(no excluyente) Plus: Valoramos mucho si tenés conocimientos en metodologías de Mejora Continua (WCM, TPM o Lean Manufacturing). Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Postulate! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores.', 0, 'Villa Gobernador Gálvez, Santa Fe', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 20:50:32', '12-04-2026 04:03:12', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.27, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227920.html', '2026-04-12T07:05:36.459426');
