, 19, 2623, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/2/0/2/1/1/0/logoMainPic_10202110.jpg', 1, 0, 3.7, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227506.html', '2026-04-12T07:05:36.459506');
