FORMACIÓN ADICIONAL AL PUESTO Horario Laboral: Full time de L a V de 8 a 17(Presencial) - La Reja, Moreno', 1, 'La Reja, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 11:28:44', '10-04-2026 11:28:44', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 2, 0, 4, 2558, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118101654.html', '2026-04-12T07:05:36.459584');
