INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118153335, 13480187, 'RECEPCIONISTA / OPERADOR DE ATENCIÓN para Nueva Empresa de Servicios de Emergencias Médicas', 'Código Comunicación', 'Somos Código Comunicación, una consultora estratégica especializada en soluciones integrales de comunicación y gestión humana. Nuestra expertise abarca desde el reclutamiento y selección de talento hasta la organización y planificación de áreas de , diseñando estructuras que potencien el capital humano y alineen a las personas con los objetivos del negocio.Nuestros servicios clave: Reclutamiento y Selección: Conectamos talentos con oportunidades laborales a nivel país, mediante metodologías ágiles y un profundo conocimiento del mercado. Diseño y Optimización de Desarrollamos estructuras organizacionales, políticas de gestión humana y planes estratégicos para maximizar el desempeño. Comunicación Interna y Employer Branding: Fortalecemos la cultura organizacional, mejorando el engagement y posicionando a las empresas como empleadores de referencia. Nueva Empresa de Servicios de Emergencias Médicas de Villa María busca incorporar personal para su área de Mesa de Entrada y Atención al Cliente. Orientamos la búsqueda a perfiles dinámicos, con excelente trato interpersonal y capacidad para gestionar tareas administrativas en entornos de ritmo constante. Misión del puestoBrindar atención telefónica y administrativa de excelencia, registrando y derivando las solicitudes de servicios médicos de manera eficiente y cordial, cumpliendo con los protocolos de la organización. Principales Responsabilidades: Atención al Cliente: Recepción de llamadas de afiliados, pacientes y empresas. Gestión de Datos: Carga precisa y registro de los servicios solicitados en el sistema. Triage Administrativo: Clasificación y derivación de solicitudes según prioridad y urgencia. Asesoramiento: Brindar información clara sobre servicios, coberturas y convenios vigentes. Confidencialidad: Manejo responsable y ético de la información médica y personal. Requisitos: Educación: Secundario completo (excluyente). Experiencia: Experiencia previa en puestos de atención al cliente, recepción o call center (preferentemente en el rubro salud). Herramientas: Manejo fluido de herramientas informáticas (Office y sistemas de gestión). Disponibilidad: Contar con disponibilidad para realizar turnos rotativos (requisito fundamental para la operativa del servicio). Beneficios Competencias valoradas: Comunicación clara, empática y capacidad de escucha activa. Organización, precisión en la carga de datos y proactividad. Capacidad para trabajar bajo presión y resolución de conflictos. Fuerte vocación de servicio. Condiciones: Lugar de trabajo: Villa María, Córdoba. Modalidad: Presencial. Jornada: Turnos rotativos.', 0, 'Villa María, Córdoba', 'Presencial', 'Full-time', '11-02-2026', '11-02-2026 13:41:19', '11-02-2026 13:41:19', '2026-02-11', NULL, NULL, '2026-02-11T00:00:00-03:00', NULL, NULL, 2, 0, 26, 2380, 1, NULL, NULL, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118153335.html', '2026-04-12T07:05:36.459980');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179259, 349876, 'Jefe de Redes y Comunicaciones', 'CREDENCIAL ARGENTINA SA', 'SOMOS LATAM, OPERAMOS EN 15 PAÍSES, DESARROLLAMOS MEDIOS DE PAGO | PAGOS DIGITALES DESDE HACE MÁS DE 40 AÑOS. Descripción del puestoBuscamos incorporar un Jefe/a de Redes y Comunicaciones estratégico y con una sólida base técnica para liderar nuestra infraestructura de conectividad. Nos orientamos a perfiles con visión de escalabilidad, enfoque en la seguridad y capacidad de liderazgo, que aseguren la continuidad operativa de servicios críticos en entornos de alta disponibilidad y procesamiento transaccional.Principales Responsabilidades Gestión de Infraestructura: Administrar y asegurar el funcionamiento óptimo de redes LAN, WAN, VPN y enlaces, garantizando la alta disponibilidad y performance del negocio. Seguridad y Compliance: Implementar políticas de seguridad de red alineadas a normativas internacionales (ej. PCI), gestionando riesgos, vulnerabilidades y soporte en auditorías. Liderazgo de Equipo: Coordinar y potenciar el desarrollo del equipo técnico a cargo, fomentando una cultura de excelencia y mejora continua. Gestión de Proveedores: Administrar la relación con Telcos, Data Centers y partners de servicios, asegurando el cumplimiento de SLAs y negociaciones eficientes. Monitoreo y Resolución: Supervisar el monitoreo proactivo de la red y liderar la resolución de incidentes técnicos complejos bajo indicadores de MTTR exigentes. Innovación y Escalabilidad: Planificar la evolución de la arquitectura de red y evaluar nuevas tecnologías para acompañar el crecimiento de la compañía. Requisitos: Formación Académica: Graduado en Ingeniería en Sistemas, Telecomunicaciones o carreras afines. Certificaciones Obligatorias: Certificación en Arquitectura AWS y Arquitectura Avanzada AWS. Experiencia: Mínimo 3 años liderando equipos de redes o comunicaciones en entornos de servicios críticos. Competencias Soft: Liderazgo inspirador, orientación a resultados, capacidad analítica para la toma de decisiones y excelentes habilidades de negociación. Networking: Dominio de arquitectura de redes LAN/WAN/VPN y protocolos de seguridad. Cloud: Especialista en arquitecturas de red sobre AWS. Seguridad: Implementación de normativas de cumplimiento y remediación de vulnerabilidades. Monitoreo: Manejo de herramientas avanzadas de gestión y observabilidad de red. Extras valorados: Certificaciones Cisco (CCNA / CCNP). Beneficios Cobertura Médica de primer nivel. Reintegro de gastos de conectividad. Modalidad Híbrida (Esquema de Home Office & Presencial) - Oficinas en CABA. Vacaciones en días hábiles. Línea de celular corporativa.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 12:34:14', '09-04-2026 12:34:14', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 34, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179259.html', '2026-04-12T07:05:36.460082');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222795, 13510729, 'Chofer Profesional', 'Industrias Ferpak', 'Chofer Profesional Resumen del Puesto Estamos en la búsqueda de un Chofer Profesional para incorporarse a nuestro equipo. El candidato ideal poseerá una licencia de conducir profesional vigente y experiencia comprobable en roles de reparto, logística o transporte de personal. Responsabilidades Conducción de unidades de la empresa. Control de carga y documentación asociada al transporte. Realización de mantenimiento preventivo básico del vehículo. Cumplimiento de horarios y rutas establecidas. Requisitos Licencia de conducir profesional vigente (categorías aplicables al tipo de vehículo). Experiencia mínima de 2 años en puestos similares. Conocimiento de rutas y manejo de documentación de transporte. Se valorará la puntualidad, el compromiso y la responsabilidad en el cuidado de la unidad.', 0, 'San Martin, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:26:38', '10-04-2026 16:26:38', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, NULL, NULL, NULL, NULL, 750, 'Aviso Express', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222795.html', '2026-04-12T07:05:36.460147');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225733, 10110006, 'Enfermero Profesional', 'S.I.S.M. PSIQUIS S.R.L.', 'Importante Institución de Salud MentalNos encontramos en la búsqueda de un Enfermero comprometido para formar parte de nuestro equipo multidisciplinario. En nuestra institución, tendrás la oportunidad de realizar asistencia a pacientes que requieren un enfoque integral y humano en su tratamiento.Valoramos la vocación de servicio, el compromiso con la excelencia en la atención de la salud y la capacidad para trabajar en equipo. Si te apasiona la enfermería y deseas formar parte de un equipo de profesionales dedicados, ¡esta es tu oportunidad!👉 Requisitos: Estudios completos en Enfermería. Matricula vigente, Nacional y Provincial. Se valorará poseer Licenciatura en Enfermería Disponibilidad horaria Se valorará contar con experiencia en instituciones de salud mental.👉¿Qué buscamos? Vocación de servicio y empatía hacia pacientes con trastornos en salud mental. Habilidad para trabajar en equipo, fomentando un ambiente colaborativo y de apoyo. Excelentes habilidades de comunicación y escucha activa.🌏 Ubicación: Munro - Zona norte (Excluyente).🔎 Trabajo Presencial - Turnos Rotativos (Mañana, Tarde y Noche) ✨ Si estás listo para hacer una diferencia en la vida de las personas y trabajar en un entorno que valora la salud mental, ¡te invitamos a postularte!', 0, 'Munro, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 16:27:16', '10-04-2026 09:04:05', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2570, 1, NULL, 1, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225733.html', '2026-04-12T07:05:36.460236');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225318, NULL, 'Vendedor/a Bilingüe (Inglés) - Mercado EE.UU', 'Confidencial', '¡Buscamos Vendedor/a B2B para sumarse a nuestro equipo! 🚀📍 Palermo, Buenos Aires 🕒 Lunes a viernes de 09:00 a 18:00 hs (Hora Argentina) 💰 USD 1.200 + Comisiones (Contratación por contrato/Contractor) 🏢 Modalidad: Presencial los primeros 3 meses, luego pasamos a esquema Híbrido.¿Quiénes somos?Somos una empresa de logística de Estados Unidos que está creciendo rápido y queremos sumar a alguien con "garra" comercial para vender en el mercado norteamericano. Nos movemos con ritmo de startup: somos ágiles, trabajamos en equipo y nos enfocamos en que las cosas pasen. Si buscás un lugar donde tu iniciativa cuente y puedas crecer, este es tu lugar.¿De qué se trata el puesto?Buscamos un Ejecutivo de Ventas (Semi-Senior) que se anime a abrir mercado. El corazón del rol es generar nuevos clientes, principalmente a través de llamadas telefónicas, y construir relaciones a largo plazo.¿No sabés nada de logística? No te preocupes. Mes 1: Te enseñamos todo sobre el negocio (operaciones y logística) desde adentro. Mes 2: Te capacitamos específicamente en ventas. Semana 6 en adelante: ¡A la cancha! Empezás a armar tu propia cartera de clientes y a cerrar negocios.¿Qué vas a hacer? Buscar y contactar nuevas empresas en EE. UU. para ofrecerles nuestros servicios. Negociar tarifas y condiciones para cerrar tratos. Cuidar y hacer crecer las cuentas que vayas consiguiendo. Trabajar codo a codo con el equipo de operaciones.¿Qué necesitamos de vos? Inglés avanzado/bilingüe (excluyente): Vas a hablar todo el día con gente en EE. UU. Experiencia en ventas (1 a 3 años): Que te sientas cómodo negociando y no le tengas miedo al teléfono. Perfil "Hunter": Que seas proactivo, te guste ir tras los resultados y seas competitivo (en el buen sentido).¿Qué suma puntos? (No es obligatorio) Si ya trabajaste con clientes de EE. UU. o sabés algo de logística/transporte.', 1, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 13:32:49', '10-04-2026 10:44:31', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 2, 1, 6, 35, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225318.html', '2026-04-12T07:05:36.460347');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178904, 664237, 'PERSONAL ADMINISTRATIVO EN OBRA SOCIAL', 'OSCONARA', '¡QUEREMOS QUE TE UNAS A NUESTRO EQUIPO DE TRABAJO! Obra Social de Conductores Navales de la República Argentina se encuentra en la búsqueda de personal administrativo para el área de Atención al afiliado en INGENIERO WHITE: Entre las tareas a realizar se encuentran: - Atención y asesoramiento de afiliados. - Gestión de autorizaciones de practicas y medicación de forma correcta, ordenada y eficaz, en tiempo y forma. - Seguimiento de casos. - Capacidad para manejar conversaciones de alto nivel de sensibilidad. - Confección de informes. - Apertura y cierre de oficina. - Otras tareas de la organización. Requisitos: - Edad: mayor de 25 años - Modalidad: Presencial - Disponibilidad full-time de lunes a viernes - Conocimiento P.M.O, NBU, Resolución 310. - Buen manejo de herramientas informáticas: Excel, Word, etc. - Excelente habilidad de redacción y dicción. - Se valora experiencia en áreas de atención al público, en entidades de salud mínima de 2 años comprobable. - EXCLUYENTE residir en Ing. White. Bahia Blanca o zonas aledañas - Preferentemente hombres Competencias requeridas: - Excelentes habilidades de comunicación, atención de servicio - Orientación a resultados, enfoque hacia procesos para mejora continua - Capacidad de análisis - Compromiso - Proactividad para realizar sus tareas - Trabajo en equipo Si consideras que tu perfil se adapta a los requerimientos detallados, y tenés ganas de trabajar en equipo, no dudes en hacernos llegar tu postulación. ¡Te esperamos!', 0, 'Ingeniero White, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 10:46:18', '10-04-2026 09:57:48', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, 0, 0, NULL, 40, 'Avisos Gold', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178904.html', '2026-04-12T07:05:36.460430');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178887, 677563, 'Abogado/a Semi Senior - Obra Social CABA Presencial', 'Conecta Recursos Huamnos', 'Abogado/a SeniorResumen del PuestoBuscamos un/a Abogado/a Senior con experiencia en litigios para unirse a nuestro equipo. El candidato ideal tendrá la capacidad de trabajar con autonomía y brindará asesoramiento legal integral.Responsabilidades Brindar asesoramiento legal integral en áreas laboral, comercial y societaria. Gestionar y dar seguimiento a procesos judiciales. Redactar escritos y acuerdos legales. Participar en audiencias, mediaciones y procesos de conciliación. Analizar contratos y evaluar riesgos legales. Intervenir en negociaciones y resolución de conflictos.Requisitos Título de Abogado/a graduado/a y matriculado/a. Más de 3 años de experiencia en litigios. Experiencia en el manejo de causas judiciales. Sólidas habilidades interpersonales y de comunicación. Capacidad para trabajar de forma autónoma.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 05:42:14', '08-04-2026 05:42:14', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 23, 93, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178887.html', '2026-04-12T07:05:36.460499');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178886, 677563, 'Analista de Convenios Sr. - Obra Social CABA Presencial', 'Conecta Recursos Huamnos', 'Analista de Convenios Sr.Resumen del PuestoBuscamos un/a Analista de Convenios Sr. para unirse a nuestro equipo. El candidato ideal tendrá experiencia en la gestión de convenios y análisis de costos en el sector salud, con una mentalidad proactiva, organizada y con visión de negocio. Se valorarán excelentes habilidades de comunicación y negociación.Responsabilidades Gestionar altas, bajas y modificaciones de prestadores en la cartilla médica. Negociar y actualizar convenios, incluyendo valores, condiciones, módulos y formas de pago. Expandir la cartilla médica incorporando nuevos prestadores y áreas de cobertura. Coordinar con áreas de auditoría médica, administrativa y transformación digital. Analizar costos prestacionales y generar reportes estratégicos. Fortalecer relaciones con prestadores existentes y potenciales.Requisitos Experiencia comprobable en gestión de convenios y análisis de costos (preferentemente en salud o medicina prepaga). Proactividad, organización y visión de negocio. Excelentes habilidades de comunicación y negociación. Disponibilidad para viajar.Beneficios Oportunidades de desarrollo profesional. Red de descuentos corporativos.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 16:55:36', '06-04-2026 16:55:36', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 23, 93, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178886.html', '2026-04-12T07:05:36.460571');
