eran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222758.html', '2026-04-12T07:05:36.461344');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223447, 13135046, 'Operador de Contact Center (Representante Comercial Telefónico) Turno tarde', 'Verisure Argentina', '¡Hagamos Match para Potenciarnos!🚀 Nuestro equipo continúa creciendo y vos podes formar parte. Buscamos una persona dinámica, proactiva y que esté lista para los desafíos que tiene el equipo de Marketing.Te invitamos a formar parte de una compañía multinacional líder en el sector de Sistemas de Seguridad, cuyo posicionamiento se centra en sus soluciones tecnológicas innovadoras, la conectividad de sus sistemas y la experiencia de cliente. Estamos presentes en 18 países alrededor del mundo y contamos con una trayectoria de más de 35 años en el mercado.Estamos en la búsqueda de Operadores de Contact Center (ventas) para incorporarse a nuestro Call Center de forma part time, en el horario de 15hs a 21hs. Orientamos nuestra búsqueda a perfiles con fuertes habilidades de ventas comerciales, capaces de persuadir, generar interés y concretar ventas de manera efectiva.Es una posición presencial en nuestras oficinas de Palermo de Lunes a Domingo con 2 francos rotativos en la semana.✅Principales desafíos: Emisión y/o recepción de llamadas comerciales para captación de nuevos clientes. Gestión seguimiento durante todo el proceso de venta hasta el cierre de la misma. Manejo simultáneo del sistema y la gestión comercial telefónica.🔎¿Qué buscamos? Experiencia en posiciones comerciales , idealmente call center / ventas en frío. Alta capacidad comercial y poder de negociación, orientadas al cumplimiento de objetivos. Disposición y experiencia para trabajar de forma dinámica y proactiva. Nivel intermedio de office (excluyente) Secundario Completo (con analítico en mano) . Esto es excluyente para avanzar en el proceso. Disponibilidad para trabajar 6 horas de Lunes a Domingos, en el horario de 15 a 21 hs, con 2 francos rotativos en la semana.¡Sumate a Verisure y disfrutá de todos estos beneficios increíbles!🚀 💰Sueldo bruto por convenio de comercio. 💸Plan de comisiones (ver si aplica dependiendo la posición) 👩‍⚕️Swiss Medical prepaga para vos y grupo familiar primario a partir del séptimo mes. 💪 Programa de Wellhub – Planes de Gimnasio 🎉 Medio día de cumpleaños. 🍬Tarjeta de snacks mensual. 📚 Beneficios corporativos (Descuentos en Universidades, Institutos de idioma, Laboratorios, Retail,y más!.) 🤟🏽Plan de carrera y capacitación continua.Sabemos que la cultura organizacional es clave para elegir tu próximo desafío profesional. Por este motivo, te queremos presentar el ADN de Verisure Argentina para que conozcas nuestra propuesta de valor que nos hace una de las mejores empresas para trabajar en nuestro país:- Pasión en todo lo que hacemos.- Compromiso para marcar la diferencia.- Innovación constante.- Ganando como equipo.- Confianza y responsabilidad.Tu próximo desafío profesional está en Verisure Argentina, una empresa Great Place to Work® Argentina 💯En Verisure estamos comprometidos con fomentar un entorno de trabajo diverso e inclusivo, reconociendo que la diversidad de pensamiento y antecedentes solo fortalece e impulsa la innovación en nuestros equipos. Rechazamos todas las formas de discriminación y prejuicio y creemos en el acceso equitativo a oportunidades para todas las personas independientemente de su género, edad, discapacidad, raza, orientación sexual u cualquier otro factor.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Part-time', '08-04-2026', '08-04-2026 13:22:10', '10-04-2026 16:06:14', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 5, 0, 25, 110, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13135046_bum_v8f08de73.jpg', 1, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/verisure', 'https://www.bumeran.com.ar/empleos/1118223447.html', '2026-04-12T07:05:36.461564');
